    // The coalesce arms toward `cap − margin`; a cap-unknown refusal
    // (E1) has no target — the retry rides the relief alone.
    coalesceTarget: learned == null
        ? null
        : max(1, learned - kMessageCapDefaultMargin),
    terminal: null,
