          slots[slot] = MediaSlotModelConfig.fromYaml(entry.value, slot: slot);
        }
      case final other:
        throw ConfigException('models.slots must be a map, got: $other');
    }
    final custom = <String, CustomModelDefinition>{};
    switch (node['custom']) {
      case null:
