      rebuilt.add(message);
      continue;
    }
    rebuilt.add(_rewriteAssistantCallIds(messages, i, slots, index, renames));
    _emitSlotResults(
      messages,
      slots,
      index,
      renames,
      attachment,
      rebuilt,
      emittedResults,
      synthesized,
    );
