/// executable persists it with the usual config save.
final class ModelsConfig {
  /// Creates an empty (or pre-populated) models config.
  ModelsConfig({
    Map<String, MediaSlotModelConfig>? slots,
    Map<String, CustomModelDefinition>? custom,
