      // survived (the result content was previously dropped as an
      // orphan — the call merged into a carrier while the result
      // stayed in the tail).
      expect(
        out.any(
          (m) =>
              m is AssistantMessage &&
              m.content.whereType<ToolCall>().any((c) => c.id == 'c1'),
        ),
