      // merge into a carrier).
      final input = [
        UserMessage.text('older turn'),
        _assistantCall('c1', 'read'),
        UserMessage.text('mid steering'),
        _result('c1', 'read'),
        UserMessage.text('newest question — must survive verbatim'),
