  List<Message> messages, {
  required int targetMessageCount,
}) {
  if (messages.length <= targetMessageCount) return messages;
  // The cut: the newest user message stays verbatim, so the droppable
  // region is [0, newestUserIndex). With no user message at all (a pure
  // tool-call transcript), the LAST message is kept instead — a request
  // must never end up empty (E3).
  var newestUserIndex = -1;
  for (var i = messages.length - 1; i >= 0; i--) {
    if (messages[i] is UserMessage) {
      newestUserIndex = i;
      break;
    }
  }
  final regionEnd = newestUserIndex >= 0
      ? newestUserIndex
      : messages.length - 1;
  if (regionEnd <= 0) return messages; // Nothing droppable (E2/E3).

  // Group the droppable region into pairing-safe units: a tool group is an
  // assistant message carrying tool calls plus the ToolResultMessages
  // answering them; every other message is its own unit.
  final units = <List<Message>>[];
  var i = 0;
  while (i < regionEnd) {
    final message = messages[i];
    final calls = message is AssistantMessage
        ? message.content.whereType<ToolCall>().toList()
        : const <ToolCall>[];
    if (calls.isEmpty) {
      units.add([message]);
      i++;
      continue;
    }
    final answered = calls.map((call) => call.id).toSet();
    final group = <Message>[message];
    var j = i + 1;
    while (j < messages.length && answered.isNotEmpty) {
      final next = messages[j];
      if (next is ToolResultMessage && answered.remove(next.toolCallId)) {
        group.add(next);
        j++;
      } else {
        break;
      }
    }
    units.add(group);
    i = j;
  }

  // Merge each unit into one user-role carrier; carriers still over the
  // target then merge together (oldest first) until one remains or the
  // count fits.
  final carriers = [for (final unit in units) _carrierOf(unit)];
  var merged = [...carriers, ...messages.sublist(regionEnd)];
  while (merged.length > targetMessageCount && carriers.length > 1) {
    final first = carriers.removeAt(0);
    final second = carriers.removeAt(0);
    carriers.insert(
      0,
      UserMessage.text('${_carrierTextOf(first)}\n${_carrierTextOf(second)}'),
    );
    merged = [...carriers, ...messages.sublist(regionEnd)];
  }
  // Over target with a single carrier left: nothing more is droppable
  // without touching the newest turn (E2/E3) — the wire gets the smallest
  // pairing-safe shape we have.
  // Pairing belt-and-suspenders: the kept tail may carry pre-broken
  // pairing in the input; the request must never propagate it.
  return repairToolPairing(merged).messages;
}

/// The compact user-role carrier for one coalesced unit.
UserMessage _carrierOf(List<Message> unit) {
  final names = <String>[
    for (final message in unit)
      if (message is AssistantMessage)
        for (final call in message.content.whereType<ToolCall>()) call.name,
  ];
  final label = names.isEmpty
      ? '${unit.length} earlier message(s)'
      : 'tool turn(s) ${names.join(', ')}';
  return UserMessage.text(
    '[coalesced $label — ${unit.length} message(s) merged to fit the '
    'provider message cap; the full history stays in the session file]',
  );
}

String _carrierTextOf(UserMessage carrier) => carrier.content as String;

Now the fix. Design: add a `verbatim` list for split tool groups. When the inner loop breaks with `answered.isNotEmpty`, the group crossed a non-matching message (stering interleave): some result answers from the kept tail (or from beyond the cut). Keep the call — and the results already matched — verbatim; do NOT consume the matched results into carriers. Then those verbatim messages go into the payload unmerged, before the carriers (position within the droppable region doesn't matter semantically; repairToolPairing hoists results next to their calls).

Implementation:

```dart
   if (calls.isEmpty) {
     units.add([message]);
     i++;
     continue;
   }
   final answered = calls.map((call) => call.id).toSet();
   final group = <Message>[message];
   var j = i + 1;
   while (j < messages.length && answered.isNotEmpty) {
     final next = messages[j];
     if (next is ToolResultMessage && answered.remove(next.toolCallId)) {
       group.add(next);
       j++;
     } else {
       break;
     }
   }
   if (answered.isNotEmpty) {
     // PR #1695: the group hit a non-matching message before every call
     // was answered — a steering user message interleaved between the
     // call and its result. Merging the call into a carrier would orphan
     // the result (repair drops it) and lose the tool content; keep the
     // call and the results already paired with it VERBATIM instead — the
     // pairing repair hoists the displaced result back next to the call.
     // The still-unmatched results are NOT consumed: they stay in the
     // stream for their own units/tail.
     verbatim.addAll(group);
     i++;
     continue;
   }
   units.add(group);
   i = j;
```

Wait: careful — after verbatim handling with `i++`, the matched results in `group` were at indexes i+1..j-1. With i++ we move to i+1 which is the first matched result → it'll be processed as its own unit → merged into a carrier — but we're keeping it verbatim in `verbatim`! Double-processing: the result would appear BOTH verbatim and in a carrier. Bad.

Fix: consume the matched results too — `i = j`? But then the steering message between i and j... in the interleave case the inner loop breaks at the steering message (j = i+1), so matched results... in probe case group=[call] only, j=i+1, i=j=i+1 → next processed is the steering user message (good, it's at regionEnd so loop ends).

Mid-region case: [user older, call c1, user steer, result c1, user newest]. Call at 1: inner loop breaks at user steer (j=2), group=[call], answered={c1} → verbatim.add(call), i=j=2. Then user steer → unit. i=3: result c1 → own unit → merged into carrier! But call c1 is verbatim → orphan result in carrier, call without result → repair synthesizes... wait no: result c1 got merged into a carrier (dropped from wire), call c1 verbatim → repair synthesizes a placeholder result. Content lost! My test asserts content survives → would fail.

So for mid-region: the result c1 IS inside the droppable region and displaced from its call. To preserve content, keep result c1 verbatim too. So verbatim handling must consume the matched results AND scan ahead to collect the displaced results answering the still-unanswered calls within the droppable region. That's what my scan approach does: scan k in j..regionEnd for ToolResultMessages answering `answered` ids.

Then: verbatim = group + displaced results found in region; mark consumed indexes; i = j (continue normal loop from the break point; consumed indexes are skipped).

Edge: unmatched results beyond regionEnd (kept tail) — not consumed, stay in tail; repair hoists them next to the verbatim call. 

Also potential duplication: a result answering c1 could appear BOTH in the droppable region (displaced, consumed verbatim) and... no, ids are unique per occurrence; there could be a duplicate id result (pathological) — the scan consumes the first occurrence matching; the tail might have another — edge enough, repair handles.

What if a displaced result is NOT found in the region (i.e., it's in the tail, probe case)? verbatim = [call] only; i=j; loop continues; steering user at regionEnd ends loop. Tail [ster, result] + verbatim call → repair hoists. 

What about a call whose result appears BEFORE the call in the region? Pathological; not handled before either — inner loop only scans forward; answered would remain → now triggers verbatim path — call kept verbatim, result earlier in region already processed as own unit/carier... content lost for that result. But that was already broken before my change (call merged into carrier, earlier result in another carrier — content lost, pairing synthesized). Not a regression; fine.

Now merging: `merged = [...verbatim, ...cariers, ...tail]`? Order: verbatim messages are oldest (they're at the start of the region generally). Cariers after. Tail last. Actually to keep rough chronological sanity, verbatim items came from positions before regionEnd, carriers too. Put verbatim first (they're usually older — the split call precedes the region content it pairs with... eh). Actually let me keep it simple and put verbatim after carriers? No: put verbatim FIRST. The repair pass reorders results next to calls anyway. Fine.

Also the merge loop condition uses `cariers.length > 1`; verbatim messages inflate merged length beyond target — same E2/E3 acceptance.

Now implement. Also update the doc invariant bullet: "Only WHOLE tool-call/result groups go" — add the interleave exception.

